package com.gomgomapps.math.core;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class NamibiaDecimalRepresentationsTest {
 @Test public void fourActualNaSixConnectionsUseFreshPublicConditions(){var p=GlobalCurriculum.packs("NA").stream().filter(x->x.id.equals("na-nied-primary-2024-v1")).findFirst().orElseThrow();Generator g=new Generator(new Random(290));for(String id:List.of(EnglishDecimalWords.READ,EnglishDecimalWords.WRITE,"decimalOrder","el_decimal_compare")){assertTrue(p.inGrade(id,6));var l=GlobalCurriculum.limits(p.id,id,6);List<String> recent=new ArrayList<>();Set<Integer> precision=new HashSet<>();Set<String> directions=new HashSet<>(),signs=new HashSet<>();for(int i=0;i<120;i++){Question q=g.next(id,recent,false,l);assertFalse(recent.contains(q.signature()));recent.add(q.signature());List<String> expected=Arrays.asList(q.answers.clone());if(id.equals("el_decimal_compare"))signs.add(expected.get(0));q.answers=new String[expected.size()];Arrays.fill(q.answers,"poison");q.expression="poison";assertTrue(id,new Checker().check(q,List.of(),expected).correct());assertFalse(HelpPlan.forQuestion(q).canTransfer());if(EnglishDecimalWords.supports(id)){String raw=q.prompt.split("\n")[1];if(id.equals(EnglishDecimalWords.READ))raw=EnglishDecimalWords.numeral(raw);precision.add(raw.length()-raw.indexOf('.')-1);}if(id.equals("decimalOrder"))directions.add(q.prompt.startsWith("큰")?"desc":"asc");}if(EnglishDecimalWords.supports(id))assertEquals(Set.of(1,2,3),precision);if(id.equals("decimalOrder"))assertEquals(Set.of("desc","asc"),directions);if(id.equals("el_decimal_compare"))assertEquals(Set.of("<","=",">"),signs);}}
 @Test public void originalZerosNumericReadingAndWordWritingRemainDistinct(){Question r=EnglishDecimalWords.make(EnglishDecimalWords.READ,"0.007");r.answers[0]="999";assertTrue(new Checker().check(r,List.of(),List.of("0.0070")).correct());assertFalse(new Checker().check(r,List.of(),List.of("0.07")).correct());Question w=EnglishDecimalWords.make(EnglishDecimalWords.WRITE,"12.070");w.answers[0]="poison";assertTrue(new Checker().check(w,List.of(),List.of("twelve point zero seven zero")).correct());assertFalse(new Checker().check(w,List.of(),List.of("twelve point seven zero")).correct());}
 @Test public void completedHelpAssemblesOnlyCheckedStudentEntriesAndKeepsZeros(){for(String id:List.of(EnglishDecimalWords.READ,EnglishDecimalWords.WRITE)){Question q=EnglishDecimalWords.make(id,"0.070");q.answers[0]="poison";q.expression="poison";assertEquals(id.equals(EnglishDecimalWords.READ)?"0.070":"zero point zero seven zero",EnglishDecimalWords.completed(q,List.of("0","3","0","7","0")));assertNull(EnglishDecimalWords.completed(q,List.of("0","3","7","0","0")));HelpPlan plan=HelpPlan.forQuestion(q);HelpPlan.Draft draft=plan.restore(null,q.id);List<String> typed=List.of("0","3","0","7","0");for(int i=0;i<typed.size();i++){draft.entries.set(i,typed.get(i));draft.stage=i+1;draft=plan.restore(draft,q.id);}assertEquals(6,draft.entries.size());assertEquals(id.equals(EnglishDecimalWords.READ)?"0.070":"zero point zero seven zero",EnglishDecimalWords.completed(q,draft.entries));assertFalse(plan.canTransfer());}}
 @Test public void decimalComparisonPublicValuesNotKeysDecideEverySign(){for(String[] pair:new String[][]{{"1.2","1.200"},{"0.007","0.07"},{"99.999","99.99"}}){Question q=new Question("el_decimal_compare",pair[0]+"  □  "+pair[1],"poison","poison");q.kind="symbol";int cmp=new java.math.BigDecimal(pair[0]).compareTo(new java.math.BigDecimal(pair[1]));String sign=cmp<0?"<":cmp>0?">":"=";assertTrue(new Checker().check(q,List.of(),List.of(sign)).correct());assertFalse(new Checker().check(q,List.of(),List.of(sign.equals("=")?"<":"=")).correct());}}
}
